import json
from pathlib import Path
ROOT = Path(__file__).parents[1]
stt = json.loads((ROOT / "artifacts/stt_results.json").read_text(encoding="utf-8"))
e2e = json.loads((ROOT / "artifacts/e2e_results.json").read_text(encoding="utf-8"))
tts = json.loads((ROOT / "artifacts/tts_results.json").read_text(encoding="utf-8"))
barge = json.loads((ROOT / "artifacts/barge_in_results.json").read_text(encoding="utf-8"))
lines = ["# Milestone 2 Real Local Speech Results", "", "Commands: python scripts/download_fixtures.py; then run each real script with PYTHONPATH=src.", "", "## STT transcripts", "", "faster-whisper 1.2.1, CTranslate2 4.8.1, tiny, CPU/int8. Cache size: 156,408,143 bytes.", "", "| Fixture | Expected | Observed | WER | ms | detected |", "|---|---|---|---:|---:|---|"]
for row in stt["results"]:
    lines.append("| {} | {} | {} | {:.4f} | {:.2f} | {} |".format(Path(row["file"]).name, row["expected"].replace("|", "/"), row["observed"].replace("|", "/"), row["wer"], row["latency_ms"], row["detected_language"]))
mean = sum(row["wer"] for row in stt["results"]) / len(stt["results"])
lines += ["", "Mean WER across eight fixture files: {:.4f}. The three Egyptian-labeled files are ar-EG FLEURS read speech, not conversational Egyptian. The two MSA-labeled files are distinct later rows with formal Arabic text from the same ar-EG source. The mixed file concatenates real Arabic and English clips; tiny Whisper omitted its English half. No dialect-quality claim is made.".format(mean), "", "## TTS", "", "Piper TTS 1.8.0 / ONNX Runtime 1.27.0, CPU. Each output is a playable local WAV.", "", "| Case | Voice | model bytes | load ms | first audio ms | synthesis ms | output s | RSS MB |", "|---|---|---:|---:|---:|---:|---:|---:|"]
for row in tts:
    lines.append("| {} | {} | {} | {:.2f} | {:.2f} | {:.2f} | {:.3f} | {:.1f} |".format(row["case"], row["voice"], row["model_bytes"], row["load_ms"], row["first_audio_ms"], row["synthesis_ms"], row["output_duration_s"], row["process_rss_mb"]))
lines += ["", "Voice sources/model cards:", "- Arabic/Jordanian Kareem: https://huggingface.co/rhasspy/piper-voices/tree/main/ar/ar_JO/kareem/medium. Model card points to arabicttstrain and says to consult that source for licensing.", "- English US Lessac: https://huggingface.co/rhasspy/piper-voices/tree/main/en/en_US/lessac/medium. Model card links the Lessac Blizzard 2013 license.", "- Redistribution licensing is not asserted; models and generated artifacts remain git-ignored.", "", "## Limits and failures", "", "- Physical microphone and speaker devices were enumerated, but unattended recording/playback was not performed; hardware latency is NOT MEASURED.", "- Real local agent path is BLOCKED: no pre-existing Ollama, llama.cpp, llama-cpp-python, Transformers, or Torch runtime/model was found.", "- Corrupt/unsupported and missing WAV input fail closed in automated tests.", "- An earlier unbounded Arabic transcript TTS attempt raised ONNX Runtime bad allocation; the bounded agent response recovered and completed.", "- STT/TTS timeout injection and forced model corruption remain NOT MEASURED rather than claimed PASS.", "- Meta/WhatsApp systems, existing HORUS runtime, credentials, providers, routing, billing, and paid services were not touched."]
(ROOT / "M2_REAL_RESULTS.md").write_text(chr(10).join(lines) + chr(10), encoding="utf-8")
s = e2e["summary"]
b = ["# Milestone 2 Benchmark", "", "Latest isolated local CPU run: 20 turns over all 8 fixture types.", "", "| Measurement | min | median | p95 | max |", "|---|---:|---:|---:|---:|"]
for key, label in [("vad_ms", "PCM validation/energy VAD ms"), ("stt_ms", "STT final ms"), ("agent_first_output_ms", "Agent first output ms"), ("tts_first_audio_ms", "TTS first-audio ms"), ("tts_synthesis_ms", "TTS synthesis ms"), ("end_to_end_ms", "End-to-end ms")]:
    row = s[key]; b.append("| {} | {} | {} | {} | {} |".format(label, row["min"], row["median"], row["p95"], row["max"]))
b += ["", "- STT model load (cached files, fresh process): {} ms; first download/load observed earlier: 25,406.15 ms.".format(s["stt_model_load_ms"]), "- Two Piper voices load: {} ms.".format(s["voice_load_ms"]), "- Mean WER: {} across {} turns / {} fixture types.".format(s["mean_wer"], s["turns"], s["fixture_types"]), "- Session continuity: {} retained turns; 10-turn assertion PASS.".format(s["context_turns"]), "- Process RSS: {} MB; CPU sample: {} percent across logical cores; GPU not used.".format(s["rss_mb"], s["cpu_percent_sample"]), "- Barge-in software sink: 10/10 cancelled, min {} ms, median {} ms, p95 {} ms. Hardware latency NOT MEASURED.".format(barge["min_ms"], barge["median_ms"], barge["p95_ms"]), "", "These are local prototype measurements, not production/WhatsApp or conversational-dialect quality claims. TTS first-audio is time until Piper yields its first sentence chunk."]
(ROOT / "M2_BENCHMARK.md").write_text(chr(10).join(b) + chr(10), encoding="utf-8")
